
(function(root){
  'use strict';
  function shift(date,days){var d=new Date(date+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10);}
  function cells(anchor,mode){var first=mode==='week'?root.FieldGoalsModel.weekStart(anchor):root.FieldGoalsModel.weekStart(anchor.slice(0,7)+'-01');var n=mode==='week'?7:42;return Array.from({length:n},function(_,i){return shift(first,i);});}
  function daily(data,day,today,progress){var out={};var imported=progress&&Array.isArray(progress.days)?progress.days.filter(function(r){return r.activityDate===day;}).sort(function(a,b){return b.reportDate.localeCompare(a.reportDate);})[0]:null;root.FieldGoalsModel.keys.forEach(function(k){var rows=data.records.filter(function(r){return r.kind===k&&r.date===day;});function count(a){return root.FieldGoalsModel.personMetrics.includes(k)?new Set(a.map(function(r){return r.personId;})).size:a.length;}out[k]={actual:progress?(imported&&day<=today&&Number.isInteger(imported.values[k])?imported.values[k]:null):count(rows.filter(function(r){return r.status==='completed'&&day<=today;})),planned:count(rows.filter(function(r){return r.status==='confirmed'&&day>=today&&r.dueDate>=today;}))};});return out;}
  function week(data,days,today,progress){var rows=days.map(function(day){return daily(data,day,today,progress);}),out={};root.FieldGoalsModel.keys.forEach(function(k){var recorded=rows.filter(function(row){return row[k].actual!==null;});out[k]={actual:recorded.length?recorded.reduce(function(n,row){return n+row[k].actual;},0):null,recordedDays:recorded.length,planned:rows.reduce(function(n,row){return n+row[k].planned;},0)};});return out;}
  var model={shift:shift,cells:cells,daily:daily,week:week};
  if(typeof module!=='undefined'&&module.exports){root.FieldGoalsModel=require('./field-model');module.exports=model;}else root.FieldCalendarModel=model;
})(typeof globalThis!=='undefined'?globalThis:this);
var fieldCalendarMode='month',fieldCalendarAnchor='';
function fieldCalendarHTML(month){
  var today=fieldGoalsToday(),data=fieldGoalsData(),known=fieldGoalsKnown();
  if(!fieldCalendarAnchor||fieldCalendarAnchor.slice(0,7)!==month)fieldCalendarAnchor=month===today.slice(0,7)?today:month+'-01';
  var days=FieldCalendarModel.cells(fieldCalendarAnchor,fieldCalendarMode),s=FieldGoalsModel.summarize(data,fieldGoalsReport(month),month,today);
  var summary=FIELD_METRICS.map(function(p){var a=s.metrics[p[0]],u=fieldUnit(p[0]),v=function(n){return n===null?'未確認':n+u;};return '<div class="field-calendar-summary"><strong>'+p[1]+'</strong><span>目標 '+v(a.goal)+' ／ 実績 '+v(a.actual)+'</span><span>残り '+v(a.gap)+' ／ 確定予定 '+(known?a.secured+u:'未取得')+' ／ 予定後 '+(known?v(a.unsecured):'未計算')+'</span><small>'+(s.remainingDays===0?'期間終了':a.gap===null?'目標・実績の確認が必要':'必要平均：1日 '+(a.gap/s.remainingDays).toFixed(2)+u+' ／ 7日 '+(a.gap*7/s.remainingDays).toFixed(2)+u)+'</small></div>';}).join('');
  return '<section class="field-section field-calendar '+(fieldCalendarMode==='month'?'is-month':'is-week')+'"><h3>行動カレンダー</h3><p>日付を押すと予定・行動記録を入力できます。実績の数値はNotionから取得します。状態が「確定」の記録は「予」に反映されます。</p><div class="field-calendar-controls"><button data-fc-mode="month" aria-pressed="'+(fieldCalendarMode==='month')+'">月</button><button data-fc-mode="week" aria-pressed="'+(fieldCalendarMode==='week')+'">週</button><button data-fc-nav="-1">前へ</button><button data-fc-nav="0">今日</button><button data-fc-nav="1">次へ</button><strong>'+esc(fieldCalendarMode==='month'?month:days[0]+'〜'+days[6])+'</strong></div><p>残り '+s.remainingDays+' 日（日本時間・今日を含む）。日別の実績はNotionの「日別数値進捗」の進捗欄を活動日に表示します。未記録は「—」です。確定予定は実績に加えません。行動記録：'+esc(FIELD_GOALS_PHASE)+'。</p><div class="field-calendar-summary-grid">'+summary+'</div><p class="field-note">人数指標の予定後の差分は、月内の新しい人として確認した記録を重複除外して計算します。提案・取消・延期・期限超過は確定予定に含めません。紹介につながる人3人の目標は別カードで管理します。</p><div class="field-calendar-grid">'+days.map(function(day,index){var counts=FieldCalendarModel.daily(data,day,today,typeof FIELD_PROGRESS==='undefined'?{days:[]}:FIELD_PROGRESS||{days:[]});return '<article class="field-calendar-day'+(day.slice(0,7)!==month?' outside':'')+(day===today?' is-today':'')+'"><button type="button" class="field-calendar-date" data-fc-day="'+day+'"'+(fieldGoalsEditingBlocked()?' disabled':'')+' aria-label="'+day+'の予定・実績を入力・変更">'+day.slice(5).replace('-','/')+'（'+['日','月','火','水','木','金','土'][new Date(day+'T00:00:00Z').getUTCDay()]+'）<small>入力・変更</small></button>'+FIELD_METRICS.map(function(p){return '<div><span>'+p[1]+'</span><span>実 '+(counts[p[0]].actual===null?'—':counts[p[0]].actual)+' / 予 '+(known?counts[p[0]].planned:'?')+fieldUnit(p[0])+'</span></div>';}).join('')+'</article>'+(index%7===6?fieldWeekTotalHTML(data,days.slice(index-6,index+1),today,known):'');}).join('')+'</div></section>';
}
function fieldWeekTotalHTML(data,days,today,known){
  var counts=FieldCalendarModel.week(data,days,today,typeof FIELD_PROGRESS==='undefined'?{days:[]}:FIELD_PROGRESS||{days:[]});
  return '<article class="field-calendar-day field-calendar-week-total" aria-label="'+days[0]+'から'+days[6]+'の週合計"><strong>週合計</strong><small>'+days[0].slice(5).replace('-','/')+'〜'+days[6].slice(5).replace('-','/')+'</small>'+FIELD_METRICS.map(function(p){var c=counts[p[0]];return '<div title="実績の記録：'+c.recordedDays+'/7日"><span>'+p[1]+'</span><span>実 '+(c.actual===null?'—':c.actual+(c.recordedDays<7?'※':''))+' / 予 '+(known?c.planned:'?')+fieldUnit(p[0])+'</span></div>';}).join('')+'<small>※ 実績は記録がある分の合計</small></article>';
}
function wireFieldCalendar(){
  document.querySelectorAll('[data-fc-day]').forEach(function(b){b.onclick=function(){openFieldCalendarDay(b.dataset.fcDay);};});
  document.querySelectorAll('[data-fc-mode]').forEach(function(b){b.onclick=function(){fieldCalendarMode=b.dataset.fcMode;renderFieldProgress();};});
  document.querySelectorAll('[data-fc-nav]').forEach(function(b){b.onclick=function(){var step=+b.dataset.fcNav;if(!step)fieldCalendarAnchor=fieldGoalsToday();else if(fieldCalendarMode==='week')fieldCalendarAnchor=FieldCalendarModel.shift(fieldCalendarAnchor,step*7);else {var d=new Date(fieldCalendarAnchor.slice(0,7)+'-01T00:00:00Z');d.setUTCMonth(d.getUTCMonth()+step);fieldCalendarAnchor=d.toISOString().slice(0,10);}fieldMonthSelection=fieldCalendarAnchor.slice(0,7);renderFieldProgress();};});
}
function openFieldCalendarDay(day){
  if(fieldGoalsEditingBlocked())return;
  var data=fieldGoalsData(),rows=data.records.filter(function(r){return r.date===day;});
  var people=Object.fromEntries(data.persons.map(function(p){return [p.id,p.name];}));
  var html='<p>予定を追加する項目を選んでください。登録済みの記録は、変更・取消できます。</p><div class="field-day-actions">'+FIELD_METRICS.map(function(p){return '<button type="button" class="btn" data-field-day-add="'+p[0]+'">'+p[1]+'を追加</button>';}).join('')+'</div><h4>この日の記録</h4>';
  html+=rows.length?'<ul class="field-day-records">'+rows.map(function(r){return '<li><button type="button" class="btn" data-field-day-edit="'+esc(r.id)+'">'+esc(FIELD_KIND_LABELS[r.kind]+' ／ '+people[r.personId]+' ／ '+FIELD_STATUS_LABELS[r.status])+'</button><p>'+esc(r.purpose)+'</p></li>';}).join('')+'</ul>':'<p>登録済みの記録はありません。</p>';
  var dialog=fieldDialog(day+'の予定・実績',html,null);
  dialog.querySelectorAll('[data-field-day-add]').forEach(function(b){b.onclick=function(){dialog.querySelector('[data-cancel]').click();openFieldRecordEditor(day.slice(0,7),null,b.dataset.fieldDayAdd,undefined,day);};});
  dialog.querySelectorAll('[data-field-day-edit]').forEach(function(b){b.onclick=function(){dialog.querySelector('[data-cancel]').click();openFieldRecordEditor(day.slice(0,7),b.dataset.fieldDayEdit);};});
}
